#!/usr/bin/env python3
# patch-158-G5: work order responses per-asset (schema + UI)
"""
Final piece of the per-asset multi-asset arc: work order details (the
EAV intake form fields like brand, serial, what's wrong) now scope to
each asset card instead of being one form per appointment.

Use case: a multi-asset appointment is bringing in two bikes for
service. Each bike has its own brand, serial number, and "what's
wrong" answer. Previously you got one form for the whole appointment;
now each asset card holds its own.

What ships:

  Schema migration (000028):
    - Adds nullable appointment_asset_id to tenant_appointment_work_order_responses
    - nullOnDelete: detaching an asset leaves its responses around
      as unpinned appointment-wide rows rather than wiping the
      staff's notes about that bike. Matches the parts pattern.
    - Indexed as wor_asset_lookup

  Model changes:
    - TenantAppointmentWorkOrderResponse: appointment_asset_id in
      $fillable + appointmentAsset() BelongsTo relation
    - TenantAppointmentAsset: workOrderResponses() HasMany

  Controller:
    - save_work_order op: accepts optional appointment_asset_id.
      Validates against the appointment's assets. The upsert key
      becomes (appointment_id, field_id, appointment_asset_id) so
      each asset gets independent responses without collision.
    - show() (multi-asset branch): eager-loads workOrderResponses
      onto each asset.

  View (show-multi-asset.blade.php):
    - Per-asset collapsible "Work order details" section inside
      each asset card. Summary shows filled-out count (e.g. 3/5).
      Opens by default if any fields are filled.
    - Display mode: identifier prominently at the top (mono font),
      other filled fields in a 2-col grid below. "Edit" button opens
      the form below.
    - Edit form: same field rendering (text/textarea/number/select)
      as the legacy view. Posts asynchronously via fetch with the
      asset id in a hidden input. Reloads on success.
    - Bottom appointment-wide work order card removed (the previous
      E5 one).
    - Old E5 work order JS handler stays in the file but harmlessly
      noops because its DOM IDs are gone. Cleanup deferred.

Note on identifier promotion:
  appointments.identifier (the promoted column used by the
  cross-appointment ?serial=ABC123 URL search) gets the last
  written identifier value. With multiple assets, this is
  last-write-wins. A future enhancement could promote per-asset
  identifiers to a separate searchable column. Deferred.

Standalone Python. Idempotent.
"""
import argparse, base64, pathlib, sys

MARKER = "MARKER-PATCH-158-G5"

